"""Frozen research feature math. Generated by prepare_assets.py; no I/O or training."""

import copy
import numpy as np
import pandas as pd
from scipy.special import expit

KEY = ["race_key", "program_no", "horse_id"]
PARTS = ["early", "last600", "late"]
CONFIG = {"close_seconds": 0.15, "front_threshold": 0.4}
DERIVED = [
    "moist_last_record_index",
    "moist_last3_record_index_mean",
    "moist_last5_record_index_best",
    "moist_last5_record_index_count",
    "profile_top2mean5",
    "profile_previous3",
    "profile_trend",
    "profile_std5",
    "profile_count3",
    "profile_previous3_count",
    "profile_valid5_support_fraction",
]
NAMES = [
    "rank_mean",
    "rank_sd",
    "distance_slope",
    "distance_sd",
    "rank_current",
    "rank_current_sd",
    "form_mean",
    "form_trend",
    "form_sd",
    "form_trend_sd",
    "early_mean",
    "early_sd",
    "close_mean",
    "close_sd",
    "risk_rate",
    "rank_n",
    "form_n",
    "early_n",
    "close_n",
    "observed_n",
    "days",
]


def prior():
    return dict(
        rank=np.zeros(2),
        rv=np.diag([2.0, 0.5]),
        form=np.zeros(2),
        fv=np.diag([1.0, 0.04]),
        section=np.zeros(2),
        sv=np.ones(2),
        n=np.zeros(4),
        risk=np.array([1.0, 49.0]),
        date=None,
        starts=0,
    )


def propagate(s, date):
    s = copy.deepcopy(s)
    days = 0.0 if s["date"] is None else max(0.0, float((date - s["date"]).days))
    dt = min(days / 30.0, 24.0)
    decay = np.exp(-days / 1500.0)
    s["rank"] *= decay
    s["rv"] = s["rv"] * decay**2 + np.diag([0.035, 0.008]) * dt
    s["rv"][0, 0] = min(s["rv"][0, 0], 2.0)
    s["rv"][1, 1] = min(s["rv"][1, 1], 0.5)
    F = np.array([[1.0, min(dt, 6.0)], [0.0, np.exp(-days / 240.0)]])
    s["form"] = F @ s["form"]
    s["fv"] = F @ s["fv"] @ F.T + np.diag([0.035, 0.003]) * dt
    s["section"] *= decay
    s["sv"] = np.minimum(s["sv"] * decay**2 + 0.04 * dt, 1.0)
    s["risk"] = np.array([1.0, 49.0]) + (s["risk"] - np.array([1.0, 49.0])) * np.exp(-days / 730.0)
    return s, days


class Filter:
    def __init__(self):
        self.horses = {}
        self.latest = None

    def query(self, horse, date, distance):
        original = self.horses.get(horse, prior())
        s, days = propagate(original, date)
        h = np.array([1.0, (float(distance) - 1500.0) / 500.0])
        v = [
            s["rank"][0],
            np.sqrt(s["rv"][0, 0]),
            s["rank"][1],
            np.sqrt(s["rv"][1, 1]),
            h @ s["rank"],
            np.sqrt(h @ s["rv"] @ h),
            *s["form"],
            np.sqrt(s["fv"][0, 0]),
            np.sqrt(s["fv"][1, 1]),
            s["section"][0],
            np.sqrt(s["sv"][0]),
            s["section"][1],
            np.sqrt(s["sv"][1]),
            s["risk"][0] / s["risk"].sum(),
            *s["n"],
            s["starts"],
            days,
        ]
        assert len(v) == len(NAMES) and np.isfinite(v).all()
        return v, original["date"]

    def update(self, g):
        date = g.race_date.iloc[0]
        assert self.latest is None or date >= self.latest
        self.latest = date
        ids = g.horse_id.to_list()
        assert len(ids) == len(set(ids))
        states = [propagate(self.horses.get(h, prior()), date)[0] for h in ids]
        distance = float(g.result_distance.iloc[0])
        h = np.array([1.0, (distance - 1500.0) / 500.0])
        mu = np.array([h @ s["rank"] for s in states])
        var = np.array([h @ s["rv"] @ h for s in states])
        rank = g.finish_order.to_numpy(float)
        normal = g.result_status.eq("finished").to_numpy() & np.isfinite(rank) & (rank > 0)
        section = g[["early_adjusted", "last600_adjusted"]].to_numpy(float, copy=True)
        section[(section[:, 0] < 10) | (section[:, 0] > 25), 0] = np.nan
        section[(section[:, 1] < 25) | (section[:, 1] > 70), 1] = np.nan
        original_section = np.array([s["section"] for s in states])
        for i, (horse, s) in enumerate(zip(ids, states)):
            others = np.arange(len(g)) != i
            good = others & normal
            if normal[i] and good.sum() >= 3:
                scale = 1 / np.sqrt(1 + np.pi * (var[i] + var[good]) / 8)
                p = expit((mu[i] - mu[good]) * scale)
                y = (rank[i] < rank[good]).astype(float) + 0.5 * (rank[i] == rank[good])
                grad = float(np.mean((y - p) * scale) * 4)
                curvature = float(np.mean(p * (1 - p) * scale**2) * 4)
                V = np.linalg.inv(np.linalg.inv(s["rv"]) + curvature * np.outer(h, h))
                s["rank"] = s["rank"] + V @ h * grad
                s["rv"] = V
                s["n"][0] += 1
            obs = float(g.record_index.iloc[i])
            if normal[i] and np.isfinite(obs):
                v = s["fv"]
                gain = v[:, 0] / (v[0, 0] + 0.8)
                residual = np.clip(
                    obs - s["form"][0], -3 * np.sqrt(v[0, 0] + 0.8), 3 * np.sqrt(v[0, 0] + 0.8)
                )
                s["form"] += gain * residual
                s["fv"] = v - np.outer(gain, v[0, :])
                s["n"][1] += 1
            for k, seconds in enumerate([0.45, 1.2]):
                good = others & normal & np.isfinite(section[:, k])
                if normal[i] and np.isfinite(section[i, k]) and good.sum() >= 3:
                    observation = (
                        original_section[good, k].mean()
                        + (np.median(section[good, k]) - section[i, k]) / seconds
                    )
                    v = s["sv"][k]
                    gain = v / (v + 1.0)
                    residual = np.clip(observation - s["section"][k], -3, 3)
                    s["section"][k] += gain * residual
                    s["sv"][k] = v * (1 - gain)
                    s["n"][2 + k] += 1
            status = g.result_status.iloc[i]
            if status in ["finished", "did_not_finish", "disqualified"]:
                s["risk"][0 if status != "finished" else 1] += 1
            s["date"] = date
            s["starts"] += 1
            self.horses[horse] = s


def generate(f, h, progress=False):
    filt = Filter()
    events = list(h.groupby("race_date", sort=True))
    cursor = 0
    values = np.zeros((len(f), len(NAMES)))
    sources = np.full(len(f), np.datetime64("NaT", "ns"), dtype="datetime64[ns]")
    for date, ix in f.groupby("cutoff_date", sort=True).indices.items():
        while cursor < len(events) and events[cursor][0] <= date:
            for _, g in events[cursor][1].groupby("race_key", sort=False):
                filt.update(g)
            cursor += 1
            if progress and cursor % 300 == 0:
                print("state history days", cursor, flush=True)
        for i in ix:
            row = f.iloc[i]
            v, source = filt.query(row.horse_id, date, row.distance_m)
            values[i] = v
            if source is not None:
                assert source <= date
                sources[i] = np.datetime64(source)
    out = pd.DataFrame(values, columns=["state_" + x for x in NAMES])
    out["state_source_date"] = pd.to_datetime(sources)
    for name in ["rank_current", "form_mean", "early_mean", "close_mean"]:
        col = "state_" + name
        grouped = out[col].groupby(f.race_key)
        out[col + "_field_gap"] = out[col] - grouped.transform("mean")
        out[col + "_field_rank"] = grouped.rank(pct=True, method="average")
    out.insert(0, "row_number", f.row_number.to_numpy())
    return out


def slots(f, h):
    out = np.full((len(f), 5), -1, dtype=np.int32)
    dates = h.race_date.to_numpy("datetime64[D]")
    cutoff = f.cutoff_date.to_numpy("datetime64[D]")
    current = f.race_date.to_numpy("datetime64[D]")
    groups = h.groupby("horse_id", sort=False).indices
    for horse, ix in f.groupby("horse_id", sort=False).indices.items():
        history = groups.get(horse)
        if history is None:
            continue
        at = np.searchsorted(dates[history], cutoff[ix], side="right") - 1
        for lag in range(5):
            pos = at - lag
            valid = pos >= 0
            source = history[np.maximum(pos, 0)]
            valid &= (current[ix] - dates[source]).astype(int) <= 730
            out[ix[valid], lag] = source[valid]
    return out


def values(h, ix, col):
    v = h[col].to_numpy(float)
    result = v[np.maximum(ix, 0)]
    return np.where(ix >= 0, result, np.nan)


def average(v, window=5):
    v = v[:, :window]
    count = np.isfinite(v).sum(axis=1)
    return np.divide(np.nansum(v, axis=1), count, out=np.full(len(v), np.nan), where=count > 0)


def historical_features(f, h, ix, adjusted):
    out = {}
    for part in PARTS:
        col = part + "_adjusted" if adjusted else part
        # No correction or missing supporting model means original seconds retained.
        v = values(h, ix, col)
        if adjusted:
            raw = values(h, ix, part)
            v = np.where(np.isfinite(v), v, raw)
        out["section_" + part + "_last"] = v[:, 0]
        out["section_" + part + "_mean3"] = average(v, 3)
        count = np.isfinite(v).sum(axis=1)
        best = np.where(np.isfinite(v), v, np.inf).min(axis=1)
        out["section_" + part + "_best5"] = np.where(count > 0, best, np.nan)
        out["section_" + part + "_n5"] = count.astype(float)
    distance = values(h, ix, "result_distance")
    out["section_previous_distance"] = distance[:, 0]
    out["section_same_distance_n5"] = (
        (distance == f.distance_m.to_numpy()[:, None]).sum(axis=1).astype(float)
    )
    for j in range(4):
        out["style_role" + str(j) + "_rate5"] = average(values(h, ix, "role" + str(j)))
    out["style_role_n5"] = np.isfinite(values(h, ix, "role")).sum(axis=1).astype(float)
    for col in [
        "solo",
        "group_mean_relative",
        "middle_gain",
        "gain400",
        "gain200",
        "recovery",
        "fade",
    ]:
        v = values(h, ix, col)
        out["style_" + col + "_mean5"] = average(v)
        if col not in ["solo", "group_mean_relative"]:
            out["style_" + col + "_n5"] = np.isfinite(v).sum(axis=1).astype(float)
    return pd.DataFrame(out, index=f.index)


history_values = values

EVENTS = [
    "front_g3f",
    "front_g1f",
    "front_g3f_adv",
    "front_g1f_adv",
    "front_top3",
    "front_fade",
    "nonfront_g3f",
    "nonfront_g1f",
    "nonfront_g3f_adv",
    "nonfront_g1f_adv",
    "nonfront_g3f_pass",
    "nonfront_g1f_pass",
]


def conditional_profiles(h, ix):
    values = {}
    for name in EVENTS:
        v = history_values(h, ix, name)
        values["rolelate_" + name + "_mean5"] = average(v)
        values["rolelate_" + name + "_n5"] = np.isfinite(v).sum(axis=1).astype(float)
    return pd.DataFrame(values)


def gate_features(f):
    names = [
        "number",
        "inner_n",
        "outer_n",
        "inner_faster_n",
        "outer_faster_n",
        "inner_front_mass",
        "outer_front_mass",
        "inner_close_front_n",
        "outer_close_front_n",
        "inner_early_n",
        "outer_early_n",
        "early_rank_fraction",
    ]
    out = pd.DataFrame(np.nan, index=f.index, columns=["dirgate_" + n for n in names])
    for ix in f.groupby("race_key", sort=False).indices.values():
        gate = f.program_no.to_numpy(float)[ix]
        early = f.section_early_mean3.to_numpy(float)[ix]
        front = f.style_role0_rate5.to_numpy(float)[ix]
        for j, idx in enumerate(ix):
            values = {"number": gate[j]}
            for side, mask in [("inner", gate < gate[j]), ("outer", gate > gate[j])]:
                ek = mask & np.isfinite(early)
                fk = mask & np.isfinite(front)
                ck = ek & fk
                values[side + "_n"] = float(mask.sum())
                values[side + "_faster_n"] = (
                    float((early[ek] < early[j]).sum())
                    if np.isfinite(early[j]) and (ek.any() or not mask.any())
                    else np.nan
                )
                values[side + "_front_mass"] = (
                    float(front[fk].sum()) if fk.any() or not mask.any() else np.nan
                )
                values[side + "_close_front_n"] = (
                    float(
                        (
                            (np.abs(early[ck] - early[j]) <= CONFIG["close_seconds"])
                            & (front[ck] >= CONFIG["front_threshold"])
                        ).sum()
                    )
                    if np.isfinite(early[j]) and (ck.any() or not mask.any())
                    else np.nan
                )
                values[side + "_early_n"] = float(ek.sum())
            known = np.isfinite(early) & (np.arange(len(ix)) != j)
            values["early_rank_fraction"] = (
                float((early[known] < early[j]).mean())
                if known.any() and np.isfinite(early[j])
                else np.nan
            )
            out.loc[idx] = [values[n] for n in names]
    return out


def profile_frame(r, f):
    h = r.sort_values(["horse_id", "race_date"]).reset_index(drop=True)
    assert not h.duplicated(["horse_id", "race_date"]).any()
    g = h.groupby("horse_id", sort=False).candidate_index
    states = h[["horse_id", "race_date"]].rename(columns={"race_date": "candidate_source_date"})
    states["moist_last_record_index"] = h.candidate_index
    states["moist_last3_record_index_mean"] = g.transform(
        lambda x: x.rolling(3, min_periods=1).mean()
    )
    states["moist_last5_record_index_best"] = g.transform(
        lambda x: x.rolling(5, min_periods=1).max()
    )
    states["moist_last5_record_index_count"] = g.transform(
        lambda x: x.rolling(5, min_periods=1).count()
    )
    states["profile_count3"] = g.transform(lambda x: x.rolling(3, min_periods=1).count())
    states["profile_previous3_count"] = g.transform(
        lambda x: x.shift(3).rolling(3, min_periods=1).count()
    )
    states["profile_previous3"] = g.transform(lambda x: x.shift(3).rolling(3, min_periods=1).mean())
    recent = states.moist_last3_record_index_mean
    states["profile_trend"] = (recent - states.profile_previous3).where(
        states.profile_count3.ge(2) & states.profile_previous3_count.ge(2)
    )
    states["profile_std5"] = g.transform(lambda x: x.rolling(5, min_periods=3).std())
    top2 = np.full(len(h), np.nan)
    values = h.candidate_index.to_numpy(float)
    for ids in h.groupby("horse_id", sort=False).indices.values():
        w = np.lib.stride_tricks.sliding_window_view(
            np.pad(values[ids], (4, 0), constant_values=np.nan), 5
        )
        known = np.isfinite(w).sum(axis=1)
        ordered = np.sort(np.where(np.isfinite(w), w, -np.inf), axis=1)
        top2[ids] = np.where(known >= 2, ordered[:, -2:].mean(axis=1), np.nan)
    states["profile_top2mean5"] = top2
    h["support_valid"] = h.supported.astype(float).where(h.candidate_index.notna())
    states["profile_valid5_support_fraction"] = h.groupby(
        "horse_id", sort=False
    ).support_valid.transform(lambda x: x.rolling(5, min_periods=1).mean())
    query = f[KEY + ["cutoff_date"]].copy()
    query["_row"] = np.arange(len(f))
    joined = pd.merge_asof(
        query.sort_values("cutoff_date"),
        states.sort_values("candidate_source_date"),
        by="horse_id",
        left_on="cutoff_date",
        right_on="candidate_source_date",
        direction="backward",
    )
    joined = joined.sort_values("_row").reset_index(drop=True)
    for col in ["moist_last5_record_index_count", "profile_count3", "profile_previous3_count"]:
        joined[col] = joined[col].fillna(0)
    result = f.copy()
    result[DERIVED] = joined[DERIVED]
    result["candidate_source_date"] = joined.candidate_source_date
    assert (
        result.candidate_source_date.isna() | result.candidate_source_date.le(result.cutoff_date)
    ).all()
    return result
